    // 2. 收集所有 __awaiter 调用
    const awaiterCalls = this.collectAwaiterCalls(sourceFile);
    this.stats.awaiterCallsFound = awaiterCalls.length;

    // 3. 转换每个 __awaiter 调用
    for (const awaiterInfo of awaiterCalls) {
